using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Quotations;using Namaa.Api.Extensions;using Namaa.Application.Quotations.Commands.AddQuotationItem;using Namaa.Application.Quotations.Commands.AddQuotationPaymentTerm;using Namaa.Application.Quotations.Commands.CreateQuotation;using Namaa.Application.Quotations.Commands.UpdateQuotation;using Namaa.Application.Quotations.Queries.GetQuotationById;using Namaa.Application.Quotations.Queries.GetQuotations;
namespace Namaa.Api.Controllers;[ApiController][Route("api/quotations")]public sealed class QuotationsController(ISender sender):ControllerBase{
[HttpPost]public async Task<IActionResult>Create(CreateQuotationRequest request,CancellationToken cancellationToken){var x=await sender.Send(new CreateQuotationCommand(request.CustomerId,request.QuotationNumber,request.Title,request.IssueDate,request.ValidUntil,request.Notes,request.Terms),cancellationToken);return x.IsFailure?x.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=x.Value.Id},x.Value);}
[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetQuotationsQuery(),cancellationToken)).ToActionResult(this);
[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetQuotationByIdQuery(id),cancellationToken)).ToActionResult(this);
[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdateQuotationRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdateQuotationCommand(id,request.Title,request.IssueDate,request.ValidUntil,request.Notes,request.Terms,request.RowVersion),cancellationToken)).ToActionResult(this);
[HttpPost("{id:long}/items")]public async Task<IActionResult>AddItem(long id,AddQuotationItemRequest request,CancellationToken cancellationToken)=>(await sender.Send(new AddQuotationItemCommand(id,request.Description,request.Quantity,request.UnitPrice,request.DiscountAmount,request.TaxAmount,request.ServiceId,request.RowVersion),cancellationToken)).ToActionResult(this);
[HttpPost("{id:long}/payment-terms")]public async Task<IActionResult>AddTerm(long id,AddQuotationPaymentTermRequest request,CancellationToken cancellationToken)=>(await sender.Send(new AddQuotationPaymentTermCommand(id,request.Percentage,request.Amount,request.Description,request.DueAfterDays,request.DueDate,request.RowVersion),cancellationToken)).ToActionResult(this);}

